-- Every table of the gate with its indexes, column for column in the shape the rows already kept read
-- in, so a table copied in keeps every column its readers name.

CREATE TABLE "gate_options" (
  "key" text NOT NULL,
  "agent" text NOT NULL,
  "thinking" bigint,
  "answer_tokens" bigint,
  "timeout_ms" bigint,
  "set_at" bigint NOT NULL,
  "enabled" bigint,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("key", "agent")
);

CREATE TABLE "gate_roads" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "stage" text NOT NULL,
  "chat_id" bigint,
  "message_id" bigint,
  "provider" text NOT NULL,
  "model" text NOT NULL,
  "outcome" text NOT NULL,
  "ms" bigint NOT NULL,
  "created_at" bigint NOT NULL,
  "input_tokens" bigint,
  "output_tokens" bigint,
  "cache_read_tokens" bigint,
  "cache_write_tokens" bigint,
  "round" text,
  "run" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  "context_ratio" double precision,
  PRIMARY KEY ("id")
);

CREATE INDEX "gate_roads_chat" ON "gate_roads" (chat_id, created_at);
CREATE INDEX "gate_roads_round" ON "gate_roads" (round);
CREATE INDEX "gate_roads_stage" ON "gate_roads" (stage, created_at);

CREATE TABLE "judgements" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "chat_id" bigint NOT NULL,
  "message_id" bigint,
  "stage" text NOT NULL,
  "verdict" text NOT NULL,
  "detail" text,
  "created_at" bigint NOT NULL,
  "ms" bigint,
  "round" text,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "judgements_chat" ON "judgements" (chat_id, created_at);
CREATE INDEX "judgements_message" ON "judgements" (chat_id, message_id);

CREATE TABLE "reference_offers" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "stage" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "message_id" bigint,
  "held" bigint NOT NULL,
  "asked" bigint NOT NULL,
  "by_item" bigint NOT NULL,
  "by_keyword" bigint NOT NULL,
  "by_person" bigint NOT NULL,
  "capped" bigint NOT NULL,
  "slugs" text NOT NULL,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  "round" text,
  "rules" text,
  PRIMARY KEY ("id")
);

CREATE INDEX "reference_offers_stage" ON "reference_offers" (stage, created_at);
CREATE INDEX "reference_offers_round" ON "reference_offers" (round);

CREATE TABLE "reference_verdicts" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "stage" text NOT NULL,
  "chat_id" bigint NOT NULL,
  "message_id" bigint,
  "slug" text NOT NULL,
  "llm" bigint,
  "attached" bigint,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "reference_verdicts_chat" ON "reference_verdicts" (chat_id, created_at);
CREATE UNIQUE INDEX "reference_verdicts_one" ON "reference_verdicts" (stage, chat_id, COALESCE(message_id, -1), slug);
CREATE INDEX "reference_verdicts_stage" ON "reference_verdicts" (stage, created_at);

CREATE TABLE "sanitised_texts" (
  "hash" text,
  "text" text NOT NULL,
  "changed" bigint NOT NULL,
  "at" text NOT NULL,
  "judged_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("hash")
);

CREATE INDEX "sanitised_texts_at" ON "sanitised_texts" (judged_at);

CREATE TABLE "document_translations" (
  "document" text NOT NULL,
  "version" text NOT NULL,
  "target" text NOT NULL,
  "part" bigint NOT NULL,
  "parts" bigint NOT NULL,
  "text" text,
  "failed" bigint NOT NULL DEFAULT 0,
  "translated_at" bigint NOT NULL,
  rowid bigint GENERATED BY DEFAULT AS IDENTITY UNIQUE,
  PRIMARY KEY ("document", "target", "version", "part")
);

CREATE TABLE "web_gate_chats" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "stage" text NOT NULL,
  "user_name" text NOT NULL,
  "prompt" text NOT NULL,
  "answer" text,
  "ms" bigint NOT NULL,
  "created_at" bigint NOT NULL,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  "user_id" bigint,
  PRIMARY KEY ("id")
);

CREATE INDEX "web_gate_chats_stage" ON "web_gate_chats" (stage, id);
